CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(150) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), is_active BOOLEAN DEFAULT true);
CREATE TABLE clients (id BIGSERIAL PRIMARY KEY, user_id BIGINT UNIQUE NOT NULL REFERENCES users(id), name VARCHAR(100) NOT NULL);
CREATE TABLE brands (id BIGSERIAL PRIMARY KEY, user_id BIGINT UNIQUE NOT NULL REFERENCES users(id), name VARCHAR(100) NOT NULL, picture_url VARCHAR(500), link_official VARCHAR(255), followers INTEGER DEFAULT 0, rating NUMERIC(2,1) DEFAULT 0, is_verified BOOLEAN DEFAULT false);
